import { readFile,writeFile,mkdtemp,rm } from 'node:fs/promises';
import { dirname,resolve,join } from 'node:path';
import { tmpdir } from 'node:os';
import { createHash } from 'node:crypto';
import { createServer } from 'vite';
import { CommerceSceneSchema } from '@still-shift/scene-contract';
import { compileCommerceComposition } from '@still-shift/animation-engine';
import { compileCommerceScene } from '@still-shift/renderer-core';
import { launchRenderBrowser,probeRenderEnvironment,assertPinnedRenderEnvironment } from '@still-shift/execution-runtime';
const root=resolve(import.meta.dirname,'../../..');
const path=join(root,'benchmarks/fixtures/ecommerce-motion/atoms/echo.json');
const input=CommerceSceneSchema.parse(JSON.parse(await readFile(path,'utf8')));
const composition=await compileCommerceComposition(input,dirname(path));
const scene=compileCommerceScene(input);
const urls=Object.fromEntries(composition.assets.map(a=>[a.id,'/@fs'+resolve(dirname(path),a.path)]));
const cache=await mkdtemp(join(tmpdir(),'ce6p-echo-diagnose-'));
const server=await createServer({root,cacheDir:cache,configFile:false,logLevel:'error',server:{host:'127.0.0.1',port:0}});
let browser;
try{
 await server.listen();browser=await launchRenderBrowser({profile:'pinned'});const page=await browser.newPage();await page.addInitScript('window.__name=(fn)=>fn;');await page.goto(server.resolvedUrls!.local[0]!);
 const environment=await probeRenderEnvironment(page,'pinned');assertPinnedRenderEnvironment(environment);
 const result=await page.evaluate(async({composition,scene,urls})=>{
  const url='/packages/renderer-core/src/index.ts';const m=await import(url);const deviceUrl='/packages/renderer-core/src/composition/render/webgl-device.ts';const {WebglDevice}=await import(deviceUrl);
  const resources=await m.loadCompositionResources(composition,id=>urls[id]);
  const legacyCanvas=document.createElement('canvas');const legacy=m.createIllustratedPreview(legacyCanvas,scene,await m.loadIllustratedImages(scene,id=>urls[id]));
  const canvasPreview=m.createCompositionPreview(document.createElement('canvas'),composition,resources,{backend:'canvas2d'});
  const gpuCanvas=document.createElement('canvas');const gpuPreview=m.createCompositionPreview(gpuCanvas,composition,resources,{backend:'webgl2'});
  const frames=[];
  const getLegacy=()=>legacyCanvas.getContext('2d').getImageData(0,0,composition.width,composition.height).data;
  try{
   for(const frame of [21,22]){legacy.renderFrame(frame);canvasPreview.renderFrame(frame);gpuPreview.renderFrame(frame);const a=getLegacy(),b=canvasPreview.readPixels(),c=gpuPreview.readPixels();
    const comparisons=[['canvas',b],['webgl',c]].map(([kind,actual])=>{const metric=m.compareFrames(a,actual,composition.width,composition.height);const offset=a.findIndex((v,i)=>i%4!==3&&Math.abs(v-actual[i])===metric.maxChannelDelta);const start=offset-offset%4;return{kind,...metric,point:{x:start/4%composition.width,y:Math.floor(start/4/composition.width)},expected:Array.from(a.slice(start,start+4)),actual:Array.from(actual.slice(start,start+4))};});
    const point=comparisons.find(v=>v.kind==='webgl').point;const trace=[];let enabled=false,kind='';const drawImage=CanvasRenderingContext2D.prototype.drawImage;const pass=WebglDevice.prototype.pass;
    CanvasRenderingContext2D.prototype.drawImage=function(...args){const result=Reflect.apply(drawImage,this,args);if(enabled&&this.canvas.width===composition.width&&this.canvas.height===composition.height){trace.push({kind,op:'drawImage',alpha:this.globalAlpha,composite:this.globalCompositeOperation,matrix:Array.from([this.getTransform().a,this.getTransform().b,this.getTransform().c,this.getTransform().d,this.getTransform().e,this.getTransform().f]),bytes:Array.from(this.getImageData(point.x,point.y,1,1).data),sourceSize:[args[0].width,args[0].height],args:args.slice(1)});}return result;};
    WebglDevice.prototype.pass=function(...args){const result=Reflect.apply(pass,this,args);if(enabled&&args[1]?.width===composition.width&&args[1]?.height===composition.height)trace.push({kind,op:'gpuPass',shader:args[0].replace(/\s+/g,' ').slice(0,350),screen:args[1].screen,uniforms:args[3],clip:args[5],rawPremultipliedBytes:Array.from(this.readRegion(args[1],point.x,point.y,1,1))});return result;};
    gpuPreview.renderFrame(0);canvasPreview.renderFrame(0);legacy.renderFrame(0);
    try{for(const [name,p]of [['legacy',legacy],['canvas',canvasPreview],['webgl',gpuPreview]]){kind=name;enabled=true;p.renderFrame(frame);enabled=false;}}
    finally{enabled=false;CanvasRenderingContext2D.prototype.drawImage=drawImage;WebglDevice.prototype.pass=pass;}
    frames.push({frame,comparisons,point,trace});
   }
   return{elapsedTimingsCaptured:false,pixelLocalStorageAvailable:gpuCanvas.getContext('webgl2').getSupportedExtensions().filter(s=>s.includes('pixel_local_storage')),frames};
  }finally{legacy.dispose();canvasPreview.dispose();gpuPreview.dispose();}
 },{composition:JSON.parse(JSON.stringify(composition)),scene:JSON.parse(JSON.stringify(scene)),urls});
 const source=await readFile(import.meta.filename,'utf8');await writeFile(join(root,'benchmarks/results/composition-ce6p/echo-stage-diagnosis.json'),JSON.stringify({environment,sourceSha256:createHash('sha256').update(source).digest('hex'),source,result},null,2)+'\n');
 console.log(JSON.stringify(result.frames.map(f=>({frame:f.frame,comparisons:f.comparisons,traceEntries:f.trace.length})),null,2));
}finally{await browser?.close();await server.close();await rm(cache,{recursive:true,force:true});}

