import{readFile,writeFile,mkdtemp,rm}from'node:fs/promises';
import{join,dirname,resolve}from'node:path';
import{tmpdir}from'node:os';
import{createHash}from'node:crypto';
import{execFileSync}from'node:child_process';
import{createServer}from'vite';
import{CommerceSceneSchema}from'@still-shift/scene-contract';
import{compileCommerceComposition}from'@still-shift/animation-engine';
import{compileCommerceScene}from'@still-shift/renderer-core';
import{launchRenderBrowser,probeRenderEnvironment,assertPinnedRenderEnvironment}from'@still-shift/execution-runtime';
import{commerceEffectVariants}from'../../../tests/helpers/composition-effects.ts';
import{commerceExposureVariants}from'../../../tests/helpers/composition-commerce-exposure.ts';
const root=resolve(import.meta.dirname,'../../..'),dir=join(root,'benchmarks/results/composition-ce6p');
const hash=(s:string|Buffer)=>createHash('sha256').update(s).digest('hex');
const cache=await mkdtemp(join(tmpdir(),'ce6p-echo-oracle-'));
const server=await createServer({root,cacheDir:cache,configFile:false,logLevel:'error',server:{host:'127.0.0.1',port:0}});let browser;
const source=await readFile(import.meta.filename,'utf8');const record:any={status:'in-progress',method:'Untimed diagnostic only. Original production renderer versus prototype-only rounded bitmap recurrence for WebglImages into transparent surfaces. Both compared with unchanged legacy pixels. No compatibility correction retained.',source,sourceSha256:hash(source),productionSha256:{},cases:[]};
for(const path of [...execFileSync('git',['ls-files','packages/renderer-core/src','packages/animation-engine/src','packages/scene-contract/src'],{encoding:'utf8'}).trim().split('\n').filter(p=>p.endsWith('.ts')),'packages/renderer-core/src/composition/render/webgl-disjoint-paints.ts'])record.productionSha256[path]=hash(await readFile(join(root,path)));
try{
 await server.listen();browser=await launchRenderBrowser({profile:'pinned'});
 for(const fixture of ['echo','motion-blur']){
  const path=join(root,`benchmarks/fixtures/ecommerce-motion/atoms/${fixture}.json`);const inputSource=await readFile(path,'utf8');record.productionSha256[path.slice(root.length+1)]=hash(inputSource);const input=CommerceSceneSchema.parse(JSON.parse(inputSource));const id='commerce/atom-'+fixture;
  const items=fixture==='echo'?[{id,scene:input},...commerceEffectVariants(id,input)]:commerceExposureVariants(id,input).filter(v=>v.id.endsWith('/overlap-echo-matte'));
  for(const item of items){
   const composition=await compileCommerceComposition(item.scene,dirname(path));const scene=compileCommerceScene(item.scene);const urls=Object.fromEntries(composition.assets.map(a=>[a.id,'/@fs'+resolve(dirname(path),a.path)]));
   const page=await browser.newPage();await page.addInitScript('window.__name=(fn)=>fn;');await page.goto(server.resolvedUrls!.local[0]!);const environment=await probeRenderEnvironment(page,'pinned');assertPinnedRenderEnvironment(environment);
   const result=await page.evaluate(async({composition,scene,urls})=>{
    const url='/packages/renderer-core/src/index.ts';const m=await import(url);const d='/packages/renderer-core/src/composition/render/webgl-device.ts';const i='/packages/renderer-core/src/composition/render/webgl-images.ts';const{WebglDevice}=await import(d);const{WebglImages}=await import(i);
    const resources=await m.loadCompositionResources(composition,id=>urls[id]);const legacyCanvas=document.createElement('canvas');const legacy=m.createIllustratedPreview(legacyCanvas,scene,await m.loadIllustratedImages(scene,id=>urls[id]));const original=m.createCompositionPreview(document.createElement('canvas'),composition,resources,{backend:'webgl2'});const candidate=m.createCompositionPreview(document.createElement('canvas'),composition,resources,{backend:'webgl2'});
    const originalPass=WebglDevice.prototype.pass,originalImages=WebglImages.prototype.draw;let enabled=false,imageDepth=0;
    WebglImages.prototype.draw=function(...args){imageDepth++;try{return Reflect.apply(originalImages,this,args);}finally{imageDepth--;}};
    WebglDevice.prototype.pass=function(...args){if(enabled&&imageDepth&&args[1]&&!args[1].opaque&&args[3]?.primitive===1)args[3]={...args[3],primitive:0};return Reflect.apply(originalPass,this,args);};
    const metric=()=>({maxDelta:0,minPsnr:999,failedFrames:[]});const before=metric(),after=metric();const hashes=[];
    const digest=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');
    try{
     for(let frame=0;frame<composition.frameCount;frame++){legacy.renderFrame(frame);const expected=legacyCanvas.getContext('2d').getImageData(0,0,composition.width,composition.height).data;for(const [p,r,prototype]of[[original,before,false],[candidate,after,true]]){enabled=prototype;p.renderFrame(frame);const actual=p.readPixels();enabled=false;const c=m.compareFrames(expected,actual,composition.width,composition.height);r.maxDelta=Math.max(r.maxDelta,c.maxChannelDelta);r.minPsnr=Math.min(r.minPsnr,c.psnr);if(!m.meetsTier(c,'near'))r.failedFrames.push(frame);if(prototype)hashes[frame]=await digest(actual);}}
     let checkedSeeks=0;enabled=true;for(const frame of [...Array.from({length:composition.frameCount},(_,i)=>composition.frameCount-1-i),...Array.from({length:17},(_,i)=>(i*73+31)%composition.frameCount),...Array(3).fill(Math.floor(composition.frameCount/2))]){candidate.renderFrame(frame);if(await digest(candidate.readPixels())!==hashes[frame])throw Error('Prototype seek mismatch '+frame);checkedSeeks++;}
     enabled=false;return{frames:composition.frameCount,before,after,checkedSeeks,elapsedTimingsCaptured:false};
    }finally{enabled=false;WebglImages.prototype.draw=originalImages;WebglDevice.prototype.pass=originalPass;candidate.dispose();original.dispose();legacy.dispose();}
   },{composition:JSON.parse(JSON.stringify(composition)),scene:JSON.parse(JSON.stringify(scene)),urls});
   record.cases.push({id:item.id,environment,...result});await writeFile(join(dir,'echo-rounding-oracle.json'),JSON.stringify(record,null,2)+'\n');console.log(JSON.stringify({id:item.id,...result}));await page.close();
  }
 }
 record.status=record.cases.every(c=>!c.after.failedFrames.length)?'passed-prototype-only':'failed-prototype-only';await writeFile(join(dir,'echo-rounding-oracle.json'),JSON.stringify(record,null,2)+'\n');if(record.status.startsWith('failed'))process.exitCode=1;
}finally{await browser?.close();await server.close();await rm(cache,{recursive:true,force:true});}

