import type { CompiledShapes } from "../shapes/types.ts";
import { compositionEffectDefinition } from "@still-shift/scene-contract";
import type { EvaluatedEffect } from "../evaluate/effects.ts";
import { evaluateComp } from "../evaluate/evaluate.ts";
import type {
  BezierPath,
  Composition,
  CompositionBlendMode,
  CompositionLayer,
  CompositionScope,
  TrackMatte,
} from "@still-shift/scene-contract";
import { multiplyMatrix, type Matrix } from "../../node-transform.ts";
import type {
  Bounds,
  EvaluatedLayer,
  EvaluatedLayerTree,
  Rgba,
  EvaluationOptions,
} from "../evaluate/types.ts";
import { cameraMatrix } from "../evaluate/camera.ts";
import { projectBounds } from "../evaluate/geometry.ts";

export type RenderEffect = EvaluatedEffect & {
  placement?: { matrix: Matrix; transforms: Matrix[] };
};

type TextLayer = Extract<CompositionLayer, { type: "text" }>;
type ImageLayer = Extract<CompositionLayer, { type: "image" }>;

/** An axis-aligned rectangle `[0, width] × [0, height]` in the space of `matrix`. */
export type ClipRect = {
  matrix: Matrix;
  transforms?: Matrix[];
  width: number;
  height: number;
};

export type MaskOp = {
  id: string;
  path: BezierPath;
  mode: "add" | "subtract" | "intersect" | "difference";
  inverted: boolean;
  feather: number;
  expansion: number;
  opacity: number;
  /** Layer space to surface space. */
  matrix: Matrix;
  transforms?: Matrix[];
};

export type SolidContent = {
  type: "solid";
  width: number;
  height: number;
  color: Rgba;
};
export type ImageContent = {
  type: "image";
  width: number;
  height: number;
  fit: "contain" | "cover" | "stretch";
  rasterize: "draw" | "natural-size";
  /** Echo history stacking uses bitmap source-over on transparent targets. */
  bitmapRounding?: true;
  sources: ImageLayer["sources"];
  state: number;
  stateFrom?: number;
  stateMix?: number;
};
export type TextContent = {
  type: "text";
  /** Root layer id or `precomp-id/layer-id`, as in `EvaluationOptions.textBounds`. */
  key: string;
  layer: TextLayer;
  /** Layer time: text transitions, decorations and animators are sampled here. */
  time: number;
  stateFrom?: number;
  stateMix?: number;
  state: number;
  reveal: number;
  color: Rgba;
};
export type SurfaceContent = { type: "surface"; surface: SurfaceNode };
export type ProviderContent = {
  type: "provider";
  key: string;
  layer: Extract<CompositionLayer, { type: "provider" }>;
  time: number;
  /** Authored source time for a provider with an explicit indexed sample clock. */
  sourceTime?: number;
  state?: number;
  stateFrom?: number;
  stateMix?: number;
};
export type ShapeContent = { type: "shape"; shapes: CompiledShapes };
export type LayerContent =
  | ShapeContent
  | SolidContent
  | ImageContent
  | TextContent
  | ProviderContent
  | SurfaceContent;

/** Draw content straight into the current surface. */
export type DrawOp = {
  kind: "draw";
  layer: string;
  content: LayerContent;
  matrix: Matrix;
  /** Preserve native Canvas concatenation precision through cameras and parents. */
  transforms: Matrix[];
  opacity: number;
  blend: CompositionBlendMode;
  clips: ClipRect[];
  paintBlur?: number;
};
/** Render `ops` into a scope-sized surface, apply masks and matte, then composite. */
export type IsolateOp = {
  kind: "isolate";
  layer: string;
  ops: RenderOp[];
  effects: RenderEffect[];
  masks: MaskOp[];
  matte: MatteOp | null;
  opacity: number;
  blend: CompositionBlendMode;
  clips: ClipRect[];
};
/** Re-composite everything below within a layer-space region (adjustment layer). */
export type AdjustOp = {
  kind: "adjust";
  layer: string;
  matrix: Matrix;
  transforms: Matrix[];
  width: number;
  height: number;
  effects: RenderEffect[];
  masks: MaskOp[];
  matte: MatteOp | null;
  opacity: number;
  blend: CompositionBlendMode;
  clips: ClipRect[];
};
export type MatteOp = {
  mode: TrackMatte["mode"];
  layer: string;
  /** Ops that draw the matte layer with its own transform, opacity, masks and matte. */
  ops: RenderOp[];
};
export type RenderOp = DrawOp | IsolateOp | AdjustOp;

/** One composition scope rendered into its own surface. */
export type SurfaceNode = {
  id: string;
  width: number;
  height: number;
  background: Rgba | null;
  ops: RenderOp[];
};

export type RenderGraph = {
  root: SurfaceNode;
  /** Layer keys skipped because their bounds miss the surface they draw into. */
  culled: string[];
};
export type RenderGraphOptions = EvaluationOptions & {
  /** Preparation must discover offscreen glyph samples before final bounds exist. */
  cull?: boolean;
};

type Frame = {
  matrix: Matrix;
  transforms: Matrix[];
  opacity: number;
  clips: ClipRect[];
  viewport: { width: number; height: number };
  /** Key prefix for layers of this scope (`""` at the root). */
  prefix: string;
  /** An ancestor effect may pull offscreen content into view. */
  cull?: boolean;
  paintBlur?: number;
};
type Scope = {
  tree: EvaluatedLayerTree;
  def: CompositionScope;
  byId: Map<string, EvaluatedLayer>;
  matteSources: Set<string>;
  containers: Set<string>;
  /** Nearest group whose children must paint together, rather than in the outer scope. */
  owners: Map<string, string>;
};

const IDENTITY: Matrix = [1, 0, 0, 1, 0, 0];

function boundsMiss(bounds: Bounds, matrix: Matrix, frame: Frame) {
  const projected =
    matrix === IDENTITY ? bounds : projectBounds(bounds, matrix);
  return (
    projected.right <= 0 ||
    projected.bottom <= 0 ||
    projected.left >= frame.viewport.width ||
    projected.top >= frame.viewport.height
  );
}

/** Tag echo content only; matte images retain their own composition semantics. */
function echoImageOps(ops: RenderOp[]): RenderOp[] {
  return ops.map((op) => {
    if (op.kind === "isolate") return { ...op, ops: echoImageOps(op.ops) };
    if (op.kind !== "draw") return op;
    if (op.content.type === "image")
      return { ...op, content: { ...op.content, bitmapRounding: true } };
    if (op.content.type === "surface")
      return { ...op, content: { ...op.content, surface: {
        ...op.content.surface, ops: echoImageOps(op.content.surface.ops),
      } } };
    return op;
  });
}

class GraphBuilder {
  readonly culled: string[] = [];
  private readonly cameras = new Map<string, Matrix>();
  private readonly history = new Map<string, Scope>();
  private readonly exposures = new WeakMap<EvaluatedLayerTree, Scope>();
  constructor(
    readonly comp: Composition,
    readonly time: number,
    readonly options: RenderGraphOptions,
    readonly historical = false,
  ) {}

  private precomp(id: string): CompositionScope {
    return this.comp.precomps!.find((p) => p.id === id)!;
  }

  surface(
    tree: EvaluatedLayerTree,
    def: CompositionScope,
    prefix: string,
  ): SurfaceNode {
    return {
      id: tree.id,
      width: tree.width,
      height: tree.height,
      background: tree.background,
      ops: this.scopeOps(tree, def, {
        matrix: IDENTITY,
        transforms: [],
        opacity: 1,
        clips: [],
        viewport: { width: tree.width, height: tree.height },
        prefix,
        ...(this.options.cull === false ? { cull: false } : {}),
      }),
    };
  }

  scopeOps(
    tree: EvaluatedLayerTree,
    def: CompositionScope,
    frame: Frame,
  ): RenderOp[] {
    return this.scopeLayers(this.scope(tree, def), frame);
  }

  private scope(tree: EvaluatedLayerTree, def: CompositionScope): Scope {
    const scope: Scope = {
      tree,
      def,
      byId: new Map(tree.layers.map((s) => [s.id, s])),
      matteSources: new Set(
        def.layers.flatMap((layer) =>
          layer.trackMatte ? [layer.trackMatte.layer] : [],
        ),
      ),
      owners: new Map(),
      containers: new Set(),
    };
    const containers = (scope.containers = new Set(
      def.layers
        .filter(
          (layer) =>
            layer.type === "group" &&
            (scope.matteSources.has(layer.id) ||
              layer.trackMatte ||
              layer.masks?.length ||
              layer.effects?.length ||
              (layer.blendMode && layer.blendMode !== "normal")),
        )
        .map((layer) => layer.id),
    ));
    if (containers.size)
      for (const layer of def.layers) {
        for (
          let parent = layer.parent;
          parent;
          parent = scope.byId.get(parent)!.layer.parent
        ) {
          if (containers.has(parent)) {
            scope.owners.set(layer.id, parent);
            break;
          }
        }
      }
    return scope;
  }

  private scopeLayers(scope: Scope, frame: Frame, owner?: string): RenderOp[] {
    const ops: RenderOp[] = [];
    // layers[0] is the top layer, so paint from the end of the list.
    for (let i = scope.tree.layers.length - 1; i >= 0; i--) {
      const state = scope.tree.layers[i]!;
      if (scope.owners.get(state.id) !== owner) continue;
      if (
        state.drawable ||
        (state.visible &&
          scope.containers.has(state.id) &&
          !scope.matteSources.has(state.id))
      )
        ops.push(...this.layerOps(scope, state, frame));
    }
    return ops;
  }

  private exposureScope(scope: Scope, state: EvaluatedLayer): Scope {
    const tree = state.exposure?.tree;
    if (!tree) return scope;
    let sample = this.exposures.get(tree);
    if (!sample) {
      sample = this.scope(tree, scope.def);
      this.exposures.set(tree, sample);
    }
    return sample;
  }

  private groupClips(scope: Scope, state: EvaluatedLayer, frame: Frame) {
    scope = this.exposureScope(scope, state);
    const clips: ClipRect[] = [];
    for (
      let parent = state.layer.parent;
      parent;
      parent = scope.byId.get(parent)!.layer.parent
    ) {
      const ancestor = scope.byId.get(parent)!;
      if (ancestor.layer.type === "group" && ancestor.layer.clip)
        clips.push({
          matrix: multiplyMatrix(frame.matrix, ancestor.screenMatrix),
          transforms: this.transforms(scope, ancestor, frame),
          width: ancestor.layer.size[0],
          height: ancestor.layer.size[1],
        });
    }
    return [...frame.clips, ...clips.reverse()];
  }

  private transforms(
    scope: Scope,
    state: EvaluatedLayer,
    frame: Frame,
  ): Matrix[] {
    scope = this.exposureScope(scope, state);
    const local: Matrix[] = [];
    let root = state;
    for (;;) {
      local.unshift(root.localMatrix);
      if (!root.layer.parent) break;
      root = scope.byId.get(root.layer.parent)!;
    }
    return [
      ...frame.transforms,
      ...(scope.def === this.comp && this.comp.camera2d
        ? [this.camera(scope.tree.time, root.layer.cameraDepth ?? 1)]
        : []),
      ...local,
    ];
  }

  private camera(time: number, depth: number): Matrix {
    const key = `${time}:${depth}`;
    let matrix = this.cameras.get(key);
    if (!matrix) {
      matrix = cameraMatrix(this.comp, time, depth);
      this.cameras.set(key, matrix);
    }
    return matrix;
  }

  private masks(
    state: EvaluatedLayer,
    matrix: Matrix,
    transforms: Matrix[],
  ): MaskOp[] {
    return state.masks.flatMap((mask) =>
      mask.mode === "none"
        ? []
        : [
            {
              id: mask.id,
              path: mask.path,
              mode: mask.mode,
              inverted: mask.inverted ?? false,
              feather: mask.feather,
              expansion: mask.expansion,
              opacity: mask.opacity,
              matrix,
              transforms,
            },
          ],
    );
  }

  /** Mattes ignore `enabled`, solo and blend mode, as in AE; in/out points still apply. */
  private matte(
    scope: Scope,
    state: EvaluatedLayer,
    frame: Frame,
    seen: Set<string>,
  ): MatteOp | null {
    const matte = state.layer.trackMatte;
    if (!matte) return null;
    const source = scope.byId.get(matte.layer)!;
    const t = source.exposure?.tree.time ?? scope.tree.time,
      layer = source.layer;
    const active =
      t >= 0 &&
      t < scope.def.frameCount &&
      t >= (layer.inPoint ?? 0) &&
      t < (layer.outPoint ?? scope.def.frameCount) &&
      !seen.has(layer.id);
    return {
      mode: matte.mode,
      layer: frame.prefix + matte.layer,
      ops: active
        ? this.layerOps(
            scope,
            source,
            { ...frame, opacity: 1 },
            {
              blend: "normal",
              seen: new Set([...seen, layer.id]),
              cull: false,
            },
          )
        : [],
    };
  }

  private content(
    scope: Scope,
    state: EvaluatedLayer,
    frame: Frame,
  ): LayerContent | null {
    const layer = state.layer;
    switch (layer.type) {
      case "shape":
        return state.shapes?.draws.length
          ? { type: "shape", shapes: state.shapes }
          : null;
      case "provider":
        return {
          type: "provider",
          key: frame.prefix ? `${scope.def.id}/${layer.id}` : layer.id,
          layer,
          time: state.sampleIndex ?? state.time,
          ...(state.sampleIndex === undefined
            ? {}
            : { sourceTime: state.time }),
          ...(layer.state !== undefined || layer.stateFrom !== undefined
            ? { state: state.state! }
            : {}),
          ...(layer.stateFrom !== undefined || state.stateMix !== 1
            ? { stateFrom: state.stateFrom!, stateMix: state.stateMix! }
            : {}),
        };
      case "solid":
        return {
          type: "solid",
          width: layer.size[0],
          height: layer.size[1],
          color: state.color!,
        };
      case "image":
        return {
          type: "image",
          width: layer.size[0],
          height: layer.size[1],
          fit: layer.fit ?? "contain",
          rasterize: layer.rasterize ?? "draw",
          sources: layer.sources,
          state: state.state ?? 0,
          ...(state.stateFrom !== undefined && state.stateMix !== undefined
            ? { stateFrom: state.stateFrom, stateMix: state.stateMix }
            : {}),
        };
      case "text":
        return {
          type: "text",
          key: frame.prefix ? `${scope.def.id}/${layer.id}` : layer.id,
          layer,
          time: state.time,
          state: state.state ?? 0,
          reveal: state.reveal ?? 1,
          color: state.color!,
          ...(layer.stateFrom !== undefined || state.stateMix !== 1
            ? { stateFrom: state.stateFrom!, stateMix: state.stateMix! }
            : {}),
        };
      case "precomp":
        return state.precomp
          ? {
              type: "surface",
              surface: this.surface(
                state.precomp,
                this.precomp(layer.comp),
                `${frame.prefix}${layer.id}/`,
              ),
            }
          : null;
      default:
        return null;
    }
  }

  /** A positive paint blur overrides inherited group blur; zero retains it. */
  private paintBlur(scope: Scope, state: EvaluatedLayer, frame: Frame): number {
    scope = this.exposureScope(scope, state);
    for (
      let current: EvaluatedLayer | undefined = state;
      current;
      current = current.layer.parent
        ? scope.byId.get(current.layer.parent)
        : undefined
    ) {
      if (current !== state && current.layer.type !== "group") continue;
      const blur = current.effects.find(
        (effect) => effect.enabled && effect.effect === "blur.primitive",
      );
      if (blur && (blur.params.radius as number) > 0)
        return blur.params.radius as number;
    }
    return frame.paintBlur ?? 0;
  }

  /** Historical input is painted before current input and this frame's pixel stack/matte. */
  private echoOps(
    scope: Scope,
    state: EvaluatedLayer,
    frame: Frame,
    echo: EvaluatedEffect,
  ): RenderOp[] {
    const { count, spacing, decay, skipUnchanged, sourceRevision } =
      echo.params as Record<string, number>;
    if (!decay) return [];
    const ops: RenderOp[] = [];
    const rootTime = state.exposure?.rootTime ?? this.time;
    const scopeTime = state.exposure?.tree.time ?? scope.tree.time;
    const builder = new GraphBuilder(this.comp, rootTime, this.options, true);
    const route = frame.prefix.split("/").filter(Boolean);
    for (let i = count!; i >= 1; i--) {
      const time = Math.max(0, scopeTime - i * spacing!);
      const key = `${frame.prefix}:${rootTime}:${time}`;
      let sample = this.history.get(key);
      if (!sample) {
        let tree = evaluateComp(this.comp, route.length ? rootTime : time, {
          ...this.options,
          ...(route.length
            ? {
                scopeTimes: {
                  ...this.options.scopeTimes,
                  [route.join("/")]: time,
                },
              }
            : {}),
        });
        for (const id of route) {
          const nested = tree.layers.find((layer) => layer.id === id)?.precomp;
          if (!nested) return ops;
          tree = nested;
        }
        sample = this.scope(tree, scope.def);
        if (this.history.size >= 16)
          this.history.delete(this.history.keys().next().value!);
        this.history.set(key, sample);
      }
      const prior = sample.byId.get(state.id)!;
      if (
        (!prior.visible && !sample.matteSources.has(state.id)) ||
        time < (prior.layer.inPoint ?? 0) ||
        time >= (prior.layer.outPoint ?? scope.def.frameCount) ||
        (skipUnchanged &&
          prior.effects.find((effect) => effect.id === echo.id)?.params
            .sourceRevision === sourceRevision)
      )
        continue;
      ops.push(
        ...builder.layerOps(
          sample,
          prior,
          { ...frame, opacity: frame.opacity * decay! ** i, cull: false },
          { raw: true, blend: "normal", cull: false },
        ),
      );
    }
    return ops;
  }

  layerOps(
    scope: Scope,
    state: EvaluatedLayer,
    frame: Frame,
    options: {
      blend?: CompositionBlendMode;
      seen?: Set<string>;
      cull?: boolean;
      raw?: boolean;
    } = {},
  ): RenderOp[] {
    const key = frame.prefix + state.id,
      layer = state.layer;
    const paintBlur = this.paintBlur(scope, state, frame);
    const matrix = multiplyMatrix(frame.matrix, state.screenMatrix);
    const transforms = this.transforms(scope, state, frame);
    const opacity = frame.opacity * state.opacity;
    const blend = options.blend ?? layer.blendMode ?? "normal";
    if (opacity <= 0) return [];
    if (
      options.cull !== false &&
      frame.cull !== false &&
      !paintBlur &&
      layer.type !== "group" &&
      !(layer.type === "precomp" && layer.collapseTransforms) &&
      state.bounds &&
      boundsMiss(state.bounds, frame.matrix, frame)
    ) {
      this.culled.push(key);
      return [];
    }
    const clips = this.groupClips(scope, state, frame);
    const masks = options.raw ? [] : this.masks(state, matrix, transforms);
    const echo =
      !options.raw && !this.historical
        ? state.effects.find(
            (effect) => effect.enabled && effect.effect === "time.echo",
          )
        : undefined;
    const effects: RenderEffect[] = (options.raw ? [] : state.effects)
      .filter(
        (effect) =>
          effect.enabled &&
          !["time.echo", "blur.primitive"].includes(effect.effect),
      )
      .map((effect) => {
        if (!compositionEffectDefinition(effect.effect)!.usesLayerSpace)
          return effect;
        const source = effect.space ? scope.byId.get(effect.space)! : state;
        return {
          ...effect,
          placement: {
            matrix: multiplyMatrix(frame.matrix, source.screenMatrix),
            transforms: this.transforms(scope, source, frame),
          },
        };
      });
    const seen = options.seen ?? new Set([layer.id]);
    const matte = options.raw ? null : this.matte(scope, state, frame, seen);
    if (echo) {
      return [
        {
          kind: "isolate",
          layer: key,
          ops: echoImageOps([
            ...this.echoOps(scope, state, frame, echo),
            ...this.layerOps(scope, state, frame, {
              ...options,
              raw: true,
              blend: "normal",
              cull: false,
            }),
          ]),
          effects,
          masks,
          matte,
          opacity: 1,
          blend,
          clips: [],
        },
      ];
    }
    if (layer.type === "adjustment") {
      if (blend === "normal" && !effects.length) return [];
      return [
        {
          kind: "adjust",
          layer: key,
          matrix,
          transforms,
          width: layer.size?.[0] ?? scope.tree.width,
          height: layer.size?.[1] ?? scope.tree.height,
          effects,
          masks,
          matte,
          opacity,
          blend,
          clips,
        },
      ];
    }
    const isolated =
      blend !== "normal" ||
      masks.length > 0 ||
      matte !== null ||
      effects.length > 0;
    let ops: RenderOp[];
    if (layer.type === "group") {
      // Group opacity is already inherited by each child, including overlapping ones.
      ops = this.scopeLayers(
        scope,
        effects.length ? { ...frame, cull: false } : frame,
        layer.id,
      );
      if (!isolated) return ops;
      return [
        {
          kind: "isolate",
          layer: key,
          ops,
          effects,
          masks,
          matte,
          opacity: 1,
          blend,
          clips: [],
        },
      ];
    } else if (layer.type === "precomp" && layer.collapseTransforms) {
      // Collapsed layers keep their own blend modes and land in this surface.
      ops = state.precomp
        ? this.scopeOps(state.precomp, this.precomp(layer.comp), {
            matrix,
            transforms,
            opacity: isolated ? state.opacity : opacity,
            clips: isolated ? [] : clips,
            viewport: frame.viewport,
            prefix: `${key}/`,
            ...(paintBlur ? { paintBlur } : {}),
            ...(effects.length || frame.cull === false ? { cull: false } : {}),
          })
        : [];
      if (!isolated) return ops;
    } else {
      const content = this.content(scope, state, frame);
      if (!content) return [];
      ops = [
        {
          kind: "draw",
          layer: key,
          content,
          matrix,
          transforms,
          opacity: isolated ? 1 : opacity,
          blend: "normal",
          clips: isolated ? [] : clips,
          ...(paintBlur ? { paintBlur } : {}),
        },
      ];
      if (!isolated) return ops;
    }
    return [
      {
        kind: "isolate",
        layer: key,
        ops,
        effects,
        masks,
        matte,
        opacity:
          layer.type === "precomp" && layer.collapseTransforms
            ? frame.opacity
            : opacity,
        blend,
        clips,
      },
    ];
  }
}

/**
 * Build the per-frame render graph from an evaluated tree. Pure: no DOM access,
 * so Node tests and future backends share one description of the frame.
 */
export function buildRenderGraph(
  comp: Composition,
  tree: EvaluatedLayerTree,
  options: RenderGraphOptions = {},
): RenderGraph {
  const builder = new GraphBuilder(comp, tree.time, options);
  return {
    root: builder.surface(tree, comp, ""),
    culled: builder.culled,
  };
}

import type { Matrix } from "../../node-transform.ts";
import type { Canvas2dBackend } from "./canvas2d.ts";
import type { ClipRect, ImageContent } from "./graph.ts";
import type { WebglPaint } from "./webgl-paint.ts";
import type { WebglDevice, WebglSurface } from "./webgl-device.ts";

type Raster = {
  key: string;
  surface: WebglSurface;
  left: number;
  top: number;
  right: number;
  bottom: number;
};

/** Preserve image sampling precision while compositing bounded textures on the GPU. */
export class WebglImages {
  private readonly cached = new Map<ImageContent["sources"], Raster>();
  private bytes = 0;
  constructor(
    private readonly device: WebglDevice,
    private readonly raster: Canvas2dBackend,
    private readonly paint: WebglPaint,
  ) {}

  private forget(sources: ImageContent["sources"]) {
    const old = this.cached.get(sources);
    if (!old) return;
    this.bytes -= old.surface.width * old.surface.height * 4;
    this.cached.delete(sources);
    this.device.release(old.surface);
  }

  draw(
    dst: WebglSurface,
    content: ImageContent,
    matrix: Matrix,
    opacity: number,
    clips: ClipRect[],
    transforms?: Matrix[],
  ) {
    const key = JSON.stringify([
      content,
      matrix,
      opacity,
      clips,
      transforms,
      dst.width,
      dst.height,
    ]);
    let entry = this.cached.get(content.sources);
    if (entry?.key !== key) {
      this.forget(content.sources);
      const world = new DOMMatrix();
      for (const local of transforms ?? [matrix])
        world.multiplySelf(new DOMMatrix(local));
      const points = [
        [0, 0],
        [content.width, 0],
        [content.width, content.height],
        [0, content.height],
      ].map(([x, y]) => world.transformPoint({ x: x!, y: y! }));
      const left = Math.max(
          0,
          Math.floor(Math.min(...points.map((p) => p.x))) - 2,
        ),
        top = Math.max(0, Math.floor(Math.min(...points.map((p) => p.y))) - 2),
        right = Math.min(
          dst.width,
          Math.ceil(Math.max(...points.map((p) => p.x))) + 2,
        ),
        bottom = Math.min(
          dst.height,
          Math.ceil(Math.max(...points.map((p) => p.y))) + 2,
        );
      if (right <= left || bottom <= top) return true;
      const width = Math.min(
          dst.width - left,
          Math.ceil((right - left) / 64) * 64,
        ),
        height = Math.min(
          dst.height - top,
          Math.ceil((bottom - top) / 64) * 64,
        ),
        bytes = width * height * 4;
      if (bytes > 128 * 1024 * 1024) return false;
      while (this.bytes + bytes > 128 * 1024 * 1024 && this.cached.size)
        this.forget(this.cached.keys().next().value!);
      // Preserve device coordinates and sampling spans while dropping unused
      // trailing rows/columns. Buckets keep the preparation pool reusable.
      const pixels = this.raster.createSurface(
        Math.min(dst.width, Math.ceil((left + width) / 256) * 256),
        Math.min(dst.height, Math.ceil((top + height) / 256) * 256),
      );
      const surface = this.device.surface(width, height);
      try {
        this.raster.drawImage(
          pixels,
          content,
          matrix,
          opacity,
          "normal",
          clips,
          transforms,
        );
        this.device.uploadRegion(surface, pixels.canvas, left, top);
      } catch (error) {
        this.device.release(surface);
        throw error;
      } finally {
        this.raster.releaseSurface(pixels);
      }
      entry = { key, surface, left, top, right, bottom };
      this.bytes += bytes;
    }
    this.cached.delete(content.sources);
    this.cached.set(content.sources, entry);
    const { surface, left, top, right, bottom } = entry;
    // Direct vector drawing and antialiased clips use Canvas primitive rounding.
    // Already-rasterized images retain bitmap source-over blending.
    this.paint.draw(
      surface,
      dst,
      { left, top, right, bottom },
      content.rasterize === "draw" || clips.length > 0,
      content.bitmapRounding === true && !dst.opaque &&
        (content.rasterize === "draw" || clips.length > 0),
    );
    return true;
  }
}

import type { Bounds } from "../evaluate/types.ts";
import type { WebglBounds } from "./webgl-bounds.ts";
import {
  inputSampler,
  type WebglDevice,
  type WebglSurface,
} from "./webgl-device.ts";
import { unionBounds } from "./webgl-vector-regions.ts";

const PAINT = `uniform vec2 origin; uniform vec2 backdropOrigin; uniform vec4 region; uniform float primitive;
void main() {
  vec2 p=gl_FragCoord.xy;
  vec4 s=vec4(0.0);
  if(p.x>=region.x && p.y>=region.y && p.x<region.z && p.y<region.w)
    s=floor(texelFetch(source,ivec2(p-origin),0)*255.0+0.5);
  vec4 d=floor(texelFetch(backdrop,ivec2(p-backdropOrigin),0)*255.0+0.5);
  pixel=(primitive > 0.5 ? s+floor(d*(256.0-s.a)/256.0) : floor(s+d*(1.0-s.a/255.0)+0.5))/255.0;
}`;

export type PreparedPaint = {
  surface: WebglSurface;
  rect: Bounds;
  primitive: boolean;
};

function batchShader(count: number) {
  const declarations: string[] = [],
    operations: string[] = [];
  for (let i = 0; i < count; i++) {
    const sampler = inputSampler(i + 1);
    if (i + 1 >= 3) declarations.push(`uniform sampler2D ${sampler};`);
    declarations.push(`uniform vec4 region${i}; uniform float primitive${i};`);
    operations.push(`if (all(greaterThanEqual(p,region${i}.xy)) && all(lessThan(p,region${i}.zw))) {
      vec4 s=floor(texelFetch(${sampler},ivec2(p-region${i}.xy),0)*255.0+0.5);
      d=primitive${i}>0.5 ? s+floor(d*(256.0-s.a)/256.0) : floor(s+d*(1.0-s.a/255.0)+0.5);
    }`);
  }
  return `${declarations.join("\n")}
    uniform vec2 backdropOrigin;
    void main() {
      vec2 p=gl_FragCoord.xy;
      vec4 d=floor(texelFetch(source,ivec2(p-backdropOrigin),0)*255.0+0.5);
      ${operations.join("\n")}
      pixel=d/255.0;
    }`;
}

/** Compose prepared primitive bytes with Canvas's integer source-over rounding. */
export class WebglPaint {
  constructor(
    private device: WebglDevice,
    private bounds: WebglBounds,
  ) {}
  hasBackdrop(dst: WebglSurface) {
    return dst.opaque || this.bounds.snapshot(dst) !== null;
  }

  /** WebGL2 guarantees 16 fragment samplers; one holds the original backdrop. */
  drawMany(parts: PreparedPaint[], dst: WebglSurface) {
    const visible = parts.filter((part) =>
      this.device.drawRegion(dst, part.rect),
    );
    for (let start = 0; start < visible.length; start += 15) {
      const batch = visible.slice(start, start + 15);
      if (batch.length === 1) {
        const part = batch[0]!;
        this.draw(part.surface, dst, part.rect, part.primitive);
        continue;
      }
      const rect = batch.map((part) => part.rect).reduce(unionBounds);
      const active = this.device.drawRegion(dst, rect)!;
      const previous = this.bounds.snapshot(dst);
      const backdrop = dst.screen ? this.device.copyRegion(dst, active) : dst;
      const output = dst.screen
        ? dst
        : this.device.surface(dst.width, dst.height, false, dst.opaque);
      const uniforms: Record<string, number | number[]> = {
        backdropOrigin: dst.screen ? [active.left, active.top] : [0, 0],
      };
      for (const [i, part] of batch.entries()) {
        uniforms[`region${i}`] = [
          part.rect.left,
          part.rect.top,
          part.rect.right,
          part.rect.bottom,
        ];
        uniforms[`primitive${i}`] = part.primitive ? 1 : 0;
      }
      try {
        this.device.pass(
          batchShader(batch.length),
          output,
          [backdrop, ...batch.map((part) => part.surface)],
          uniforms,
          false,
          dst.screen ? active : previous ? unionBounds(previous, rect) : rect,
        );
        if (!dst.screen) this.device.swap(dst, output);
        this.bounds.include(dst, rect);
      } finally {
        if (dst.screen) this.device.release(backdrop);
        else this.device.release(output);
      }
    }
  }

  draw(
    source: WebglSurface,
    dst: WebglSurface,
    rect: Bounds,
    primitive = true,
    bitmapRounding = false,
  ) {
    const active = this.device.drawRegion(dst, rect);
    if (!active) return;
    if (!primitive && !dst.floating && !bitmapRounding) {
      const gl = this.device.gl;
      gl.enable(gl.BLEND);
      gl.blendEquation(gl.FUNC_ADD);
      gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      try {
        this.device.pass(
          `uniform vec2 origin; void main() {
            pixel=texelFetch(source,ivec2(gl_FragCoord.xy-origin),0);
          }`,
          dst,
          [source],
          { origin: [rect.left, rect.top] },
          true,
          active,
        );
        this.bounds.include(dst, rect);
      } finally {
        gl.disable(gl.BLEND);
      }
      return;
    }
    const previous = this.bounds.snapshot(dst);
    const backdrop = dst.screen ? this.device.copyRegion(dst, active) : dst;
    const output = dst.screen
      ? dst
      : this.device.surface(dst.width, dst.height, false, dst.opaque);
    try {
      this.device.pass(
        PAINT,
        output,
        [source, backdrop],
        {
          origin: [rect.left, rect.top],
          backdropOrigin: dst.screen ? [active.left, active.top] : [0, 0],
          region: [rect.left, rect.top, rect.right, rect.bottom],
          primitive: primitive && !bitmapRounding ? 1 : 0,
        },
        false,
        dst.screen ? active : previous ? unionBounds(previous, rect) : rect,
      );
      if (!dst.screen) this.device.swap(dst, output);
      this.bounds.include(dst, rect);
    } finally {
      if (dst.screen) this.device.release(backdrop);
      else this.device.release(output);
    }
  }
}

