from pathlib import Path
import difflib,json,hashlib
root=Path.cwd();out=root/'benchmarks/results/composition-ce6p/echo-scoped-proposal';out.mkdir(exist_ok=True)
base='packages/renderer-core/src/composition/render/'
def modify(file,changes):
 path=base+file;original=(root/path).read_text();s=original
 for before,after in changes:
  if s.count(before)!=1:raise RuntimeError(f'{file}: expected unique seam: {before!r}')
  s=s.replace(before,after)
 (out/(file+'.source')).write_text(s)
 return path,original,s
helper='''/** Tag echo content only; matte images retain their own composition semantics. */
function echoImageOps(ops: RenderOp[]): RenderOp[] {
  return ops.map((op) => {
    if (op.kind === "isolate") return { ...op, ops: echoImageOps(op.ops) };
    if (op.kind !== "draw") return op;
    if (op.content.type === "image")
      return { ...op, content: { ...op.content, bitmapRounding: true } };
    if (op.content.type === "surface")
      return { ...op, content: { ...op.content, surface: {
        ...op.content.surface, ops: echoImageOps(op.content.surface.ops),
      } } };
    return op;
  });
}

'''
files=[
 modify('graph.ts', [('  rasterize: "draw" | "natural-size";','  rasterize: "draw" | "natural-size";\n  /** Echo history stacking uses bitmap source-over on transparent targets. */\n  bitmapRounding?: true;'),('class GraphBuilder {',helper+'class GraphBuilder {'),('          ops: [\n            ...this.echoOps','          ops: echoImageOps([\n            ...this.echoOps'),('              cull: false,\n            }),\n          ],','              cull: false,\n            }),\n          ]),')]),
 modify('webgl-images.ts',[('      content.rasterize === "draw" || clips.length > 0,\n    );','      content.rasterize === "draw" || clips.length > 0,\n      content.bitmapRounding === true && !dst.opaque &&\n        (content.rasterize === "draw" || clips.length > 0),\n    );')]),
 modify('webgl-paint.ts',[('    primitive = true,\n  ) {','    primitive = true,\n    bitmapRounding = false,\n  ) {'),('    if (!primitive && !dst.floating) {','    if (!primitive && !dst.floating && !bitmapRounding) {'),('          primitive: primitive ? 1 : 0,','          primitive: primitive && !bitmapRounding ? 1 : 0,')]),
]
patch=''.join(''.join(difflib.unified_diff(a.splitlines(True),b.splitlines(True),fromfile='a/'+path,tofile='b/'+path)) for path,a,b in files)
(out/'proposal.patch').write_text(patch)
(out/'manifest.json').write_text(json.dumps({'status':'proposal-only-not-retained','method':'Vite injects these alternate sources only for isolated diagnostic pages. Production files remain unchanged. Known echo byte correction still awaits explicit compatibility approval. The per-content marker participates in existing visual/raster/isolate keys; no ambient state is used. Matte ops are deliberately excluded.','files':{path:{'baselineSha256':hashlib.sha256(a.encode()).hexdigest(),'proposalSha256':hashlib.sha256(b.encode()).hexdigest(),'source':b} for path,a,b in files}},indent=2)+'\n')
print('Prepared proposal only:',len(files),'alternate files')

