import {
  PreparedNodeSchema,
  type CommerceScene,
} from "@still-shift/scene-contract";
import { primitiveBlurVariants } from "./composition-primitive-blur.ts";
import { motionPathVariants } from "./composition-motion-path.ts";
import { numericTypographyVariants } from "./composition-typography.ts";

export function commerceExposureVariants(id: string, source: CommerceScene) {
  if (id === "typography/commerce")
    return [
      { id: "native", scene: source },
      ...numericTypographyVariants(source),
    ].map((item) => {
      const scene = structuredClone(item.scene) as CommerceScene;
      scene.effects = [
        ...(scene.effects ?? []),
        { type: "motion-blur", shutterAngle: 360, samples: 2 },
      ];
      return { id: `${id}/motion-blur-${item.id}`, scene };
    });
  if (
    [
      "component/commerce-state",
      "commerce/atom-path",
      "component/commerce-value",
    ].includes(id)
  ) {
    const scene =
      id === "component/commerce-state"
        ? primitiveBlurVariants(id, source)[0]!.scene
        : id === "commerce/atom-path"
          ? motionPathVariants(id, source)[2]!.scene
          : structuredClone(source);
    scene.effects = [
      ...(scene.effects ?? []),
      { type: "motion-blur", shutterAngle: 360, samples: 2 },
    ];
    return [{ id: `${id}/motion-blur`, scene }];
  }
  if (id !== "commerce/atom-motion-blur") return [];
  const wide = structuredClone(source);
  wide.effects = [{ type: "motion-blur", shutterAngle: 360, samples: 32 }];
  const zero = structuredClone(source);
  zero.effects = [{ type: "motion-blur", shutterAngle: 0, samples: 2 }];
  const cuts = structuredClone(source);
  cuts.effects = [
    {
      type: "motion-blur",
      shutterAngle: 360,
      samples: 4,
    },
    {
      type: "glow",
      target: "product",
      radius: 3,
      intensity: 0.2,
      threshold: 0.1,
      active: { start: 12, end: 40 },
    },
  ];
  cuts.visibility = [{ target: "product", start: 15, end: 70 }];
  cuts.events.push({
    node: "product",
    property: "opacity",
    start: 18,
    end: 28,
    from: 0.3,
    to: 0.8,
    easing: "linear",
  });
  const layered = structuredClone(source);
  layered.nodes.find((node) => node.id === "product")!.opacity = 0.6;
  layered.nodes.push(
    PreparedNodeSchema.parse({
      id: "badge",
      parent: "product",
      type: "rect",
      x: 100,
      y: 120,
      width: 240,
      height: 160,
      fill: "#db8452",
      radius: 12,
      opacity: 0.65,
    }),
  );
  layered.nodes.push(
    PreparedNodeSchema.parse({
      id: "mask",
      type: "rect",
      x: 380,
      y: 320,
      width: 330,
      height: 480,
      fill: "#ffffff",
      radius: 20,
      opacity: 0.7,
    }),
  );
  layered.mattes = [
    {
      target: "product",
      mask: "mask",
      invert: true,
      space: "canvas",
      order: "after-effects",
    },
  ];
  layered.effects = [
    { type: "motion-blur", shutterAngle: 270, samples: 4 },
    { type: "echo", target: "product", spacing: 2, count: 3, decay: 0.5 },
    {
      type: "glow",
      target: "product",
      radius: 4,
      intensity: 0.3,
      threshold: 0.1,
    },
  ];
  return [
    { id: `${id}/wide-32`, scene: wide },
    { id: `${id}/zero`, scene: zero },
    { id: `${id}/active-cuts`, scene: cuts },
    { id: `${id}/overlap-echo-matte`, scene: layered },
  ];
}

tests/helpers/composition-commerce-masks.source:
import {
  PreparedNodeSchema,
  type CommerceScene,
} from "@still-shift/scene-contract";

/** Check group flattening, shared alpha sources and visibility beyond the CE0 samples. */
export function commerceMaskVariants(id: string, source: CommerceScene) {
  if (id !== "commerce/atom-matte") return [];
  const inverted = structuredClone(source);
  inverted.mattes![0]!.invert = true;
  const product = inverted.nodes.find((node) => node.id === "product")!;
  product.opacity = 0.65;
  product.rotation = 13;
  if (product.type === "group") product.clip = true;
  inverted.nodes.find((node) => node.id === "alpha-mask")!.opacity = 0.6;
  const art = inverted.nodes.find((node) => node.id === "product-art")!;
  inverted.nodes.push({ ...art, id: "overlap", x: 35, opacity: 0.7 });

  const shared = structuredClone(source);
  const index = shared.nodes.findIndex((node) => node.id === "alpha-mask");
  const mask = shared.nodes[index]!;
  if (mask.type !== "image") throw new Error("Expected image matte");
  shared.nodes[index] = PreparedNodeSchema.parse({
    id: mask.id,
    x: mask.x,
    y: mask.y,
    width: mask.width,
    height: mask.height,
    origin: mask.origin,
    type: "group",
    rotation: 9,
    opacity: 0.55,
    clip: true,
  });
  shared.nodes.push({
    ...mask,
    id: "alpha-image",
    parent: mask.id,
    x: 0,
    y: 0,
  });
  shared.nodes.push({
    ...mask,
    id: "alpha-overlap",
    parent: mask.id,
    x: 75,
    y: 20,
    opacity: 0.5,
  });
  shared.visibility = [{ target: mask.id, start: 20, end: 200 }];
  const target = shared.nodes.find((node) => node.id === "product")!;
  const image = shared.nodes.find((node) => node.id === "product-art")!;
  shared.nodes.push({ ...target, id: "second", x: 60, opacity: 0.6 });
  shared.nodes.push({ ...image, id: "second-art", parent: "second" });
  shared.mattes!.push({
    ...shared.mattes![0]!,
    target: "second",
    invert: true,
  });
  return [
    { id: `${id}/inverted-overlap`, scene: inverted },
    { id: `${id}/shared-group-source`, scene: shared },
  ];
}

