    "git",
    [
      "ls-files",
      "packages/renderer-core/src",
      "packages/animation-engine/src",
      "packages/scene-contract/src",
    ],
    { cwd: root, encoding: "utf8" },
  )
    .trim()
    .split("\n")
    .filter((p) => p.endsWith(".ts")),
  "packages/renderer-core/src/composition/render/webgl-disjoint-paints.ts",
  "tests/helpers/composition-effects.ts",
  "tests/helpers/composition-commerce-exposure.ts",
  "tests/helpers/composition-commerce-masks.ts",
];
for (const path of paths)
  snapshots.set(join(root, path), await readFile(join(root, path), "utf8"));
for (const [path, entry] of Object.entries(manifest.files) as [string, any][]) {
  if (hash(snapshots.get(join(root, path))!) !== entry.baselineSha256)
    throw Error("Proposal parent changed: " + path);
  if (hash(entry.source) !== entry.proposalSha256)
    throw Error("Proposal fingerprint changed: " + path);
}
const source = await readFile(import.meta.filename, "utf8");
const report: any = {
  status: "in-progress",
  profile,
  pixelsOnly,
  method:
    "Untimed scoped proposal only; unchanged legacy pixels and tiers, complete timelines and seeks. Alternate sources injected into a separate Vite server; production files untouched. Echo-disabled control compared byte-for-byte with preserved source snapshot. Not retained correction or acceptance.",
  source,
  sourceSha256: hash(source),
  proposal: manifest,
  candidateSourceSha256: Object.fromEntries(
    Object.entries(manifest.files).map(([p, e]: [string, any]) => [
      p,
      hash(e.source),
    ]),
  ),
  baselineSourceSha256: Object.fromEntries(
    [...snapshots].map(([p, s]) => [p.slice(root.length + 1), hash(s)]),
  ),
  cases: [],
};
let browser, originalServer, candidateServer, cacheA, cacheB;
const retain = () => writeFile(output, JSON.stringify(report, null, 2) + "\n");
try {
  cacheA = await mkdtemp(join(tmpdir(), "ce6p-echo-base-"));
  cacheB = await mkdtemp(join(tmpdir(), "ce6p-echo-scoped-"));
  const candidateSnapshots = new Map(snapshots);
  for (const [path, entry] of Object.entries(manifest.files) as [string, any][])
    candidateSnapshots.set(join(root, path), entry.source);
  const config = (cacheDir: string, map: Map<string, string>) => ({
    root,
    cacheDir,
    configFile: false as const,
    logLevel: "error" as const,
    plugins: [
      {
        name: "immutable-echo-sources",
        enforce: "pre" as const,
        load(id: string) {
          return map.get(id);
        },
      },
    ],
    server: { host: "127.0.0.1", port: 0 },
  });
  originalServer = await createServer(config(cacheA, snapshots));
  await originalServer.listen();
  candidateServer = await createServer(config(cacheB, candidateSnapshots));
  await candidateServer.listen();
  browser = await launchRenderBrowser({ profile });
  for (const fixture of ["echo", "motion-blur"]) {
    const path = join(
      root,
      `benchmarks/fixtures/ecommerce-motion/atoms/${fixture}.json`,
    );
    const inputSource = await readFile(path, "utf8");
    report.baselineSourceSha256[path.slice(root.length + 1)] =
      hash(inputSource);
    const input = CommerceSceneSchema.parse(JSON.parse(inputSource));
    const id = "commerce/atom-" + fixture;
    const items =
      fixture === "echo"
        ? [
            { id, scene: input },
            ...commerceEffectVariants(id, input),
            {
              id: id + "/disabled-control",
              scene: {
                ...input,
                effects: input.effects.filter((e) => e.type !== "echo"),
              },
              control: true,
            },
          ]
        : commerceExposureVariants(id, input).filter((v) =>
            v.id.endsWith("/overlap-echo-matte"),
          );
    for (const item of items.filter(
      (item) =>
        !process.argv.includes("--only") ||
        item.id === process.argv[process.argv.indexOf("--only") + 1],
    )) {
      const composition = await compileCommerceComposition(
        item.scene,
        dirname(path),
      );
      const scene = compileCommerceScene(item.scene);
      const urls = Object.fromEntries(
        composition.assets.map((a) => [
          a.id,
          "/@fs" + resolve(dirname(path), a.path),
        ]),
      );
      const payload = {
        composition: JSON.parse(JSON.stringify(composition)),
        scene: JSON.parse(JSON.stringify(scene)),
        urls,
      };
      const page = await browser.newPage();
      await page.addInitScript("window.__name=(fn)=>fn;");
      await page.goto(candidateServer.resolvedUrls!.local[0]!);
      const environment = await probeRenderEnvironment(page, profile);
      if (profile === "pinned") assertPinnedRenderEnvironment(environment);
      const run = async (page: any, legacyCheck: boolean) =>
        page.evaluate(
          async ({
            composition,
            scene,
            urls,
            legacyCheck,
            pixelsOnly,
            sampleFrames,
          }) => {
            const url = "/packages/renderer-core/src/index.ts";
            const m = await import(url);
            let legacy, preview;
            try {
              const resources = await m.loadCompositionResources(
                composition,
                (id) => urls[id],
              );
              const canvas = document.createElement("canvas");
              if (legacyCheck)
                legacy = m.createIllustratedPreview(
                  canvas,
                  scene,
                  await m.loadIllustratedImages(scene, (id) => urls[id]),
                );
              preview = m.createCompositionPreview(
                document.createElement("canvas"),
                composition,
                resources,
                { backend: "webgl2" },
              );
              const digest = async (bytes: Uint8ClampedArray) =>
                Array.from(
                  new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)),
                )
                  .map((v) => v.toString(16).padStart(2, "0"))
                  .join("");
              const hashes: string[] = [];
              const sampledPixels = [];
              const metric = {
                maxDelta: 0,
                minPsnr: 999,
                failedFrames: [] as number[],
              };
              for (const frame of pixelsOnly
                ? sampleFrames
                : Array.from(
                    { length: composition.frameCount },
                    (_, frame) => frame,
                  )) {
                preview.renderFrame(frame);
                const actual = preview.readPixels();
                hashes[frame] = await digest(actual);
                if (pixelsOnly) {
                  const stream = new Blob([actual])
                    .stream()
                    .pipeThrough(new CompressionStream("deflate"));
                  const encoded = new Uint8Array(
                    await new Response(stream).arrayBuffer(),
                  );
                  let binary = "";
                  for (let i = 0; i < encoded.length; i += 32768)
                    binary += String.fromCharCode(
                      ...encoded.subarray(i, i + 32768),
                    );
                  sampledPixels.push({
                    frame,
                    pixelsDeflateBase64: btoa(binary),
                  });
                }
                if (legacyCheck) {
                  legacy.renderFrame(frame);
                  const expected = canvas
                    .getContext("2d")
                    .getImageData(
                      0,
                      0,
                      composition.width,
                      composition.height,
                    ).data;
                  const c = m.compareFrames(
                    expected,
                    actual,
                    composition.width,
                    composition.height,
                  );
                  metric.maxDelta = Math.max(
                    metric.maxDelta,
                    c.maxChannelDelta,
                  );
                  metric.minPsnr = Math.min(metric.minPsnr, c.psnr);
                  if (!m.meetsTier(c, "near")) metric.failedFrames.push(frame);
                }
              }
              let checkedSeeks = 0;
              if (legacyCheck && !pixelsOnly)
                for (const frame of [
                  ...Array.from(
                    { length: composition.frameCount },
                    (_, i) => composition.frameCount - i - 1,
                  ),
                  ...Array.from(
                    { length: 17 },
                    (_, i) => (i * 73 + 31) % composition.frameCount,
                  ),
                  ...Array(3).fill(Math.floor(composition.frameCount / 2)),
                ]) {
                  preview.renderFrame(frame);
                  if ((await digest(preview.readPixels())) !== hashes[frame])
                    throw Error("Seek mismatch " + frame);
                  checkedSeeks++;
                }
              return {
                frames: pixelsOnly ? sampleFrames.length : composition.frameCount,
                size: [composition.width, composition.height],
                sampledPixels,
                ...metric,
                hashes,
                checkedSeeks,
                elapsedTimingsCaptured: false,
              };
            } finally {
              try {
                preview?.dispose();
              } finally {
                legacy?.dispose();
              }
            }
          },
          {
            ...payload,
            legacyCheck,
            pixelsOnly,
            sampleFrames: item.id.endsWith("returning-matte")
              ? [69, 72]
              : item.id.endsWith("image-active-stack")
                ? [10, 20]
                : item.id.endsWith("overlap-echo-matte")
                  ? [15, 17]
                  : item.id === "commerce/atom-echo"
                    ? [21, 22]
                    : [0, 239],
          },
        );
      const result = await run(page, true);
      await page.close();
      let preservedBytes;
      if ("control" in item) {
        const baseline = await browser.newPage();
        await baseline.addInitScript("window.__name=(fn)=>fn;");
        await baseline.goto(originalServer.resolvedUrls!.local[0]!);
        const old = await run(baseline, false);
        await baseline.close();
        preservedBytes = {
          frames: old.frames,
          exact: old.hashes.every((h, i) => h === result.hashes[i]),
          baselineHashes: old.hashes,
        };
        if (!preservedBytes.exact) throw Error("Disabled echo bytes changed");
      }
      report.cases.push({
        id: item.id,
        environment,
        suppliedPayloadSha256: Object.fromEntries(
          Object.entries(payload).map(([key, value]) => [
            key,
            hash(JSON.stringify(value)),
          ]),
        ),
        ...result,
        preservedBytes,
      });
      await retain();
      console.log(
        JSON.stringify({
          id: item.id,
          maxDelta: result.maxDelta,
          minPsnr: result.minPsnr,
          failures: result.failedFrames.length,
          checkedSeeks: result.checkedSeeks,
          preservedBytes: preservedBytes?.exact,
        }),
      );
    }
  }
  report.status = report.cases.every((c) => !c.failedFrames.length)
    ? "passed-proposal-only"
    : "failed-proposal-only";
  await retain();
  if (report.status.startsWith("failed")) process.exitCode = 1;
} catch (error) {
  report.status = "failed-attempt";
  report.error = String(error);
  await retain();
  throw error;
} finally {
  const cleanupErrors: string[] = [];
  try {
    const closed = await Promise.allSettled([
      browser?.close(),
      originalServer?.close(),
      candidateServer?.close(),
    ]);
    for (const result of closed)
      if (result.status === "rejected")
        cleanupErrors.push(String(result.reason));
  } finally {
    const removed = await Promise.allSettled([
      cacheA && rm(cacheA, { recursive: true, force: true }),
      cacheB && rm(cacheB, { recursive: true, force: true }),
    ]);
    for (const result of removed)
      if (result.status === "rejected")
        cleanupErrors.push(String(result.reason));
    if (cleanupErrors.length) {
      report.status = "cleanup-failed";
      report.cleanupErrors = cleanupErrors;
      await retain();
      process.exitCode = 1;
    }
  }
}

