import { readFile, writeFile, mkdtemp, rm } from "node:fs/promises";
import { join, dirname, resolve } from "node:path";
import { tmpdir } from "node:os";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { createServer } from "vite";
import { CommerceSceneSchema } from "@still-shift/scene-contract";
import { compileCommerceComposition } from "@still-shift/animation-engine";
import { compileCommerceScene } from "@still-shift/renderer-core";
import {
  launchRenderBrowser,
  probeRenderEnvironment,
  assertPinnedRenderEnvironment,
} from "@still-shift/execution-runtime";
import { commerceEffectVariants } from "../../../tests/helpers/composition-effects.ts";
import { commerceExposureVariants } from "../../../tests/helpers/composition-commerce-exposure.ts";
const root = resolve(import.meta.dirname, "../../.."),
  dir = join(root, "benchmarks/results/composition-ce6p");
const profile = process.argv.includes("--hardware") ? "hardware" : "pinned";
const pixelsOnly = process.argv.includes("--pixels-only");
const hash = (s: string | Buffer) =>
  createHash("sha256").update(s).digest("hex");
const output = resolve(
  process.argv.includes("--output")
    ? process.argv[process.argv.indexOf("--output") + 1]!
    : join(dir, `echo-production-oracle-${profile}.json`),
);
const baselineRef = "633138b1a3995e9afa439f7baba3c83a3c865477";
const snapshots = new Map<string, string>();
const paths = [
  ...execFileSync(
    "git",
    [
      "ls-files",
      "packages/renderer-core/src",
      "packages/animation-engine/src",
      "packages/scene-contract/src",
    ],
    { cwd: root, encoding: "utf8" },
  )
    .trim()
    .split("\n")
    .filter((p) => p.endsWith(".ts")),
  "packages/renderer-core/src/composition/render/webgl-disjoint-paints.ts",
  "tests/helpers/composition-effects.ts",
  "tests/helpers/composition-commerce-exposure.ts",
  "tests/helpers/composition-commerce-masks.ts",
];
for (const path of paths)
  snapshots.set(join(root, path), await readFile(join(root, path), "utf8"));
const baselineSnapshots = new Map<string, string>();
for (const path of paths) {
  if (!execFileSync("git", ["ls-tree", "--name-only", baselineRef, path], { cwd: root, encoding: "utf8" }).trim()) continue;
  baselineSnapshots.set(join(root, path), execFileSync("git", ["show", `${baselineRef}:${path}`], { cwd: root, encoding: "utf8" }));
}
const source = await readFile(import.meta.filename, "utf8");
const report: any = {
  status: "in-progress",
  profile,
  pixelsOnly,
  method: pixelsOnly
    ? "Untimed retained production samples: two selected frames per case, no seek coverage. Unchanged legacy comparison and tiers; sampled pinned/hardware agreement evaluated separately. Immutable working-tree sources; baseline 633138b control."
    : "Untimed retained production correction: complete six selected timelines and seeks. Unchanged legacy comparison and tiers. Immutable working-tree sources; echo-disabled control byte-compared against baseline 633138b. Full milestone acceptance remains separate.",
  source,
  sourceSha256: hash(source),
  productionRendererVersion: "composition-webgl2-0.42.0",
  baselineRef,
  candidateSourceSha256: Object.fromEntries([...snapshots].map(([p,s]) => [p.slice(root.length+1), hash(s)])),
  baselineSourceSha256: Object.fromEntries([...baselineSnapshots].map(([p,s]) => [p.slice(root.length+1), hash(s)])),
  cases: [],
};
let browser, originalServer, candidateServer, cacheA, cacheB;
const retain = () => writeFile(output, JSON.stringify(report, null, 2) + "\n");
try {
  cacheA = await mkdtemp(join(tmpdir(), "ce6p-echo-base-"));
  cacheB = await mkdtemp(join(tmpdir(), "ce6p-echo-scoped-"));
  const candidateSnapshots = snapshots;
  const config = (cacheDir: string, map: Map<string, string>) => ({
    root,
    cacheDir,
    configFile: false as const,
    logLevel: "error" as const,
    plugins: [
      {
        name: "immutable-echo-sources",
        enforce: "pre" as const,
        load(id: string) {
          return map.get(id);
        },
      },
    ],
    server: { host: "127.0.0.1", port: 0 },
  });
  originalServer = await createServer(config(cacheA, baselineSnapshots));
  await originalServer.listen();
  candidateServer = await createServer(config(cacheB, candidateSnapshots));
  await candidateServer.listen();
  browser = await launchRenderBrowser({ profile });
  for (const fixture of ["echo", "motion-blur"]) {
    const path = join(
      root,
      `benchmarks/fixtures/ecommerce-motion/atoms/${fixture}.json`,
    );
    const inputSource = await readFile(path, "utf8");
    report.baselineSourceSha256[path.slice(root.length + 1)] =
      hash(inputSource);
    const input = CommerceSceneSchema.parse(JSON.parse(inputSource));
    const id = "commerce/atom-" + fixture;
    const items =
      fixture === "echo"
        ? [
            { id, scene: input },
            ...commerceEffectVariants(id, input),
            {
              id: id + "/disabled-control",
              scene: {
                ...input,
                effects: input.effects.filter((e) => e.type !== "echo"),
              },
              control: true,
            },
          ]
        : commerceExposureVariants(id, input).filter((v) =>
            v.id.endsWith("/overlap-echo-matte"),
          );
    for (const item of items.filter(
      (item) =>
        !process.argv.includes("--only") ||
        item.id === process.argv[process.argv.indexOf("--only") + 1],
    )) {
      const composition = await compileCommerceComposition(
        item.scene,
        dirname(path),
      );
      const scene = compileCommerceScene(item.scene);
      const urls = Object.fromEntries(
        composition.assets.map((a) => [
          a.id,
          "/@fs" + resolve(dirname(path), a.path),
        ]),
      );
      const payload = {
        composition: JSON.parse(JSON.stringify(composition)),
        scene: JSON.parse(JSON.stringify(scene)),
        urls,
      };
      const page = await browser.newPage();
      await page.addInitScript("window.__name=(fn)=>fn;");
      await page.goto(candidateServer.resolvedUrls!.local[0]!);
      const environment = await probeRenderEnvironment(page, profile);
      if (profile === "pinned") assertPinnedRenderEnvironment(environment);
      const run = async (page: any, legacyCheck: boolean) =>
        page.evaluate(
          async ({
            composition,
            scene,
            urls,
            legacyCheck,
            pixelsOnly,
            sampleFrames,
          }) => {
            const url = "/packages/renderer-core/src/index.ts";
            const m = await import(url);
            let legacy, preview;
            try {
              const resources = await m.loadCompositionResources(
                composition,
                (id) => urls[id],
              );
              const canvas = document.createElement("canvas");
              if (legacyCheck)
                legacy = m.createIllustratedPreview(
                  canvas,
                  scene,
                  await m.loadIllustratedImages(scene, (id) => urls[id]),
                );
              preview = m.createCompositionPreview(
                document.createElement("canvas"),
                composition,
                resources,
                { backend: "webgl2" },
              );
              const digest = async (bytes: Uint8ClampedArray) =>
                Array.from(
                  new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)),
                )
                  .map((v) => v.toString(16).padStart(2, "0"))
                  .join("");
              const hashes: string[] = [];
              const sampledPixels = [];
              const metric = {
                maxDelta: 0,
                minPsnr: 999,
                failedFrames: [] as number[],
              };
              for (const frame of pixelsOnly
                ? sampleFrames
                : Array.from(
                    { length: composition.frameCount },
                    (_, frame) => frame,
                  )) {
                preview.renderFrame(frame);
                const actual = preview.readPixels();
                hashes[frame] = await digest(actual);
                if (pixelsOnly) {
                  const stream = new Blob([actual])
                    .stream()
                    .pipeThrough(new CompressionStream("deflate"));
                  const encoded = new Uint8Array(
