          minPsnr: result.minPsnr,
          failures: result.failedFrames.length,
          checkedSeeks: result.checkedSeeks,
          preservedBytes: preservedBytes?.exact,
        }),
      );
    }
  }
  for (const [assetPath, sha] of Object.entries(report.assetsSha256))
    if (hash(await readFile(assetPath)) !== sha)
      throw Error("Asset changed during run: " + assetPath);
