      throw Error("Production source changed during run: " + path);
  report.sourcesVerifiedUnchanged = true;
  if (!report.cases.length) throw Error("No production echo cases selected");
  report.status = report.cases.every((c) => !c.failedFrames.length)
    ? "passed-production-correction"
    : "failed-production-correction";
  await retain();
  if (report.status.startsWith("failed")) process.exitCode = 1;
} catch (error) {
  report.status = "failed-attempt";
  report.error = String(error);
  await retain();
  throw error;
} finally {
  const cleanupErrors: string[] = [];
  try {
    const closed = await Promise.allSettled([
      browser?.close(),
      originalServer?.close(),
      candidateServer?.close(),
    ]);
    for (const result of closed)
      if (result.status === "rejected")
        cleanupErrors.push(String(result.reason));
  } finally {
    const removed = await Promise.allSettled([
      cacheA && rm(cacheA, { recursive: true, force: true }),
      cacheB && rm(cacheB, { recursive: true, force: true }),
    ]);
    for (const result of removed)
      if (result.status === "rejected")
        cleanupErrors.push(String(result.reason));
    if (cleanupErrors.length) {
      report.status = "cleanup-failed";
      report.cleanupErrors = cleanupErrors;
      await retain();
      process.exitCode = 1;
    }
  }
}

import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { dirname } from "node:path";
import { commerceEffectVariants } from "../../../tests/helpers/composition-effects.ts";
import { commerceExposureVariants } from "../../../tests/helpers/composition-commerce-exposure.ts";
import assert from "node:assert/strict";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative, resolve } from "node:path";
import {
  CommerceSceneSchema,
  type CommerceScene,
  type StoryScene,
} from "@still-shift/scene-contract";
import {
  compileCommerceComposition,
  renderComposition,
} from "@still-shift/animation-engine";
import type { CompositionBackend } from "@still-shift/renderer-core";
import { runCli } from "../../../tools/still-shift-cli/src/cli.ts";

/** Verify that compiled adapter scenes remain portable through CLI JSON and export. */
async function assertAdapterExport(
  source: CommerceScene | StoryScene,
  sourceDirectory: string,
  id: string,
  backend: CompositionBackend = "canvas2d",
) {
  const directory = await mkdtemp(join(tmpdir(), "still-shift-ce4b-export-"));
  const record: any = { id, status: "in-progress", exports: [] };
  report.cases.push(record);
  try {
    await retain();
    const scene = structuredClone(source);
    for (const asset of [...scene.assets, ...(scene.fonts ?? [])])
      asset.path = relative(directory, resolve(sourceDirectory, asset.path));
    const sourcePath = join(directory, "scene.json");
    const compositionPath = join(directory, "composition.json");
    await writeFile(sourcePath, JSON.stringify(scene));
    let errors = "";
    const args = [
      "comp",
      "export-json",
      "--scene",
      sourcePath,
      "--output",
      compositionPath,
    ];
    assert.equal(
      await runCli(args, {
        stdout: () => {},
        stderr: (text) => {
          errors += text;
        },
      }),
      0,
      errors,
    );
    const exported = JSON.parse(await readFile(compositionPath, "utf8"));
    assert.equal(exported.schemaVersion, "composition-1");
    record.status = "compiled";
    record.compositionSha256 = hash(await readFile(compositionPath));
    await retain();
    const first = await renderComposition({
      compositionPath,
      backend,
      outputPath: join(directory, "first.mp4"),
    });
    record.exports.push(first);
    record.status = "first-export-complete";
    await retain();
    assert.match(first.metrics.gpuRenderer, / composition-webgl2-0\.42\.0$/);
    const second = await renderComposition({
      compositionPath,
      backend,
      outputPath: join(directory, "second.mp4"),
    });
    record.exports.push(second);
    record.status = "second-export-complete";
    await retain();
    assert.match(second.metrics.gpuRenderer, / composition-webgl2-0\.42\.0$/);
    assert.equal(first.frameCount, scene.frameCount);
    assert.equal(first.checksums.output, second.checksums.output);
    assert.deepEqual(first.systemFontLayers, []);
    assert.equal(await runCli(args, { stdout: () => {}, stderr: () => {} }), 1);
    assert.equal(first.rendererVersion, "composition-webgl2-0.42.0");
    assert.equal(second.rendererVersion, first.rendererVersion);
    Object.assign(record, {
      status: "passed",
      id,
      frames: first.frameCount,
      firstOutputSha256: first.checksums.output,
      secondOutputSha256: second.checksums.output,
      rendererVersion: first.rendererVersion,
      relocatedAssets: true,
      overwriteProtection: true,
    });
    await retain();
    console.log(
      `CE4b ${backend} ${id} export: ${scene.frameCount} frames, two byte-identical MP4s; relocated assets and overwrite protection pass`,
    );
  } catch (e) {
    record.status = "failed-attempt";
    record.error = String(e);
    await retain();
    throw e;
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}

const root = resolve(import.meta.dirname, "../../.."),
  dir = join(root, "benchmarks/results/composition-ce6p");
const hash = (s: string | Buffer) =>
  createHash("sha256").update(s).digest("hex");
const output = join(dir, "echo-production-exports.json");
const report: any = {
  status: "in-progress",
  date: new Date().toISOString(),
  method:
    "Four corrected fixture variants independently exported via CLI composition JSON twice each with relocated assets and overwrite protection, full original frame counts. Unchanged export method; incidental export elapsed metrics are retained but excluded from performance/acceptance claims. No frozen baseline regeneration.",
  sourceSha256: {},
  assetsSha256: {},
  cases: [],
};
const retain = () => writeFile(output, JSON.stringify(report, null, 2) + "\n");
try {
  const runner = await readFile(import.meta.filename, "utf8");
  report.source = runner;
  report.runnerSha256 = hash(runner);
  const paths = execFileSync(
    "git",
    [
      "ls-files",
      "packages/renderer-core/src",
      "packages/animation-engine/src",
      "packages/scene-contract/src",
      "packages/execution-runtime/src",
      "tools/still-shift-cli/src",
      "tests/helpers",
    ],
    { cwd: root, encoding: "utf8" },
  )
    .trim()
    .split("\n")
    .filter((p) => p.endsWith(".ts"));
  paths.push(
    "packages/renderer-core/src/composition/render/webgl-disjoint-paints.ts",
  );
  for (const path of paths)
    report.sourceSha256[path] = hash(await readFile(join(root, path)));
  for (const fixture of ["echo", "motion-blur"]) {
    const path = join(
      root,
      `benchmarks/fixtures/ecommerce-motion/atoms/${fixture}.json`,
    );
    const raw = await readFile(path, "utf8");
    report.sourceSha256[path] = hash(raw);
    const source = CommerceSceneSchema.parse(JSON.parse(raw));
    const id = "commerce/atom-" + fixture;
    const variants =
      fixture === "echo"
        ? [
            { id, scene: source },
            ...commerceEffectVariants(id, source).filter(
              (x) =>
                x.id.endsWith("/returning-matte") ||
                x.id.endsWith("/image-active-stack"),
            ),
          ]
        : commerceExposureVariants(id, source).filter((x) =>
            x.id.endsWith("/overlap-echo-matte"),
          );
    for (const item of variants) {
      const comp = await compileCommerceComposition(item.scene, dirname(path));
      for (const asset of comp.assets) {
        const p = resolve(dirname(path), asset.path);
        const sha = hash(await readFile(p));
        if (report.assetsSha256[p] && report.assetsSha256[p] !== sha)
          throw Error("Asset changed: " + p);
        report.assetsSha256[p] = sha;
      }
      await assertAdapterExport(item.scene, dirname(path), item.id, "webgl2");
    }
  }
  for (const [p, sha] of Object.entries(report.sourceSha256))
    if (hash(await readFile(resolve(root, p))) !== sha)
      throw Error("Source changed: " + p);
  for (const [p, sha] of Object.entries(report.assetsSha256))
    if (hash(await readFile(p)) !== sha) throw Error("Asset changed: " + p);
  if (report.cases.length !== 4)
    throw Error("Expected four corrected export cases");
  report.sourcesAndAssetsVerifiedUnchanged = true;
  report.status = "passed";
  await retain();
} catch (e) {
  report.status = "failed-attempt";
  report.error = String(e);
  await retain();
  throw e;
}

